package com.oms.order.service;

import java.util.*;
import static com.oms.order.service.OrderValues.*;

/** Business routing adapter. Planned carrier, original WMS code and actual parcel identity stay separate. */
final class SharedCarrierRouting {
    private final OrderRepository repository;
    private final SharedCarrierService carriers;
    SharedCarrierRouting(OrderRepository repository){this.repository=repository;this.carriers=new SharedCarrierService(repository);}
    Map<String,Object> context(Map<String,Object> shipment,Map<String,Object> route,String purpose){Map<String,Object> c=new LinkedHashMap<>();c.put("system_type","WMS");c.put("provider",route.get("provider"));c.put("purpose",purpose);c.put("connection_id",String.valueOf(route.get("connection_id")));c.put("owner_code",shipment.get("owner_code"));c.put("real_store_code",shipment.get("real_store_code"));return c;}
    Map<String,Object> planned(String company,Map<String,Object> shipment,Map<String,Object> payload){Map<String,Object> route=object(payload.get("route")),ctx=context(shipment,route,"WMS_OUTBOUND_CREATE");long standard=number(shipment,"standard_id");if(standard==0){List<Long> ids=repository.db().queryForList("SELECT id FROM oms_carrier_standard WHERE company_code=? AND standard_code=?",Long.class,company,text(shipment,"carrier_code"));require(ids.size()==1,"请选择公共标准快递；原仓库编码不能作为标准身份");standard=ids.get(0);}require(number(shipment,"mandated_standard_id")==0||number(shipment,"mandated_standard_id")==standard,"计划快递与平台明确指定不一致，请重新匹配后下发");ctx.put("standard_id",standard);ctx.put("direction","OUT");ctx.put("province",OrderCarrierPolicy.province(text(object(payload.get("receiver")),"province")));ctx.put("product_code",text(shipment,"carrier_product"));Map<String,Object> r=carriers.convert(company,ctx);if(!Boolean.TRUE.equals(r.get("available"))){issue(company,shipment,"PLAN","OUTBOUND_DISPATCH",ctx,r);throw new IllegalArgumentException(text(r,"message"));}payload.put("standard_id",standard);payload.put("carrier_code",r.get("standard_code"));payload.put("carrier_name",r.get("standard_name"));payload.put("warehouse_carrier_code",r.get("external_code"));payload.put("carrier_conversion",r);return r;}
    Map<String,Object> actual(String company,Map<String,Object> shipment,String raw){List<Map<String,Object>> rows=repository.db().query("SELECT payload_json FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=?",ROW,company,shipment.get("id"));require(rows.size()==1,"实际物流缺少原WMS下发目标");Map<String,Object> payload=object(rows.get(0).get("payload_json")),ctx=context(shipment,object(payload.get("route")),"WMS_OUTBOUND_ACTUAL");ctx.put("direction","IN");ctx.put("external_code",raw);Map<String,Object> resolved=carriers.convert(company,ctx),out=new LinkedHashMap<>();out.put("carrier_code",Boolean.TRUE.equals(resolved.get("available"))?resolved.get("standard_code"):"");out.put("carrier_name",Boolean.TRUE.equals(resolved.get("available"))?resolved.get("standard_name"):"");out.put("warehouse_carrier_code",raw);out.put("standard_id",resolved.get("standard_id"));out.put("carrier_resolution_state",resolved.get("state"));out.put("carrier_resolution_json",encode(resolved));out.put("carrier_context",ctx);return out;}
    void issue(String company,Map<String,Object> shipment,String fact,String action,Map<String,Object> ctx,Map<String,Object> result){Map<String,Object> business=new LinkedHashMap<>();business.put("business_type","SHIPMENT");business.put("business_id",shipment.get("id"));business.put("business_sn",shipment.get("shipment_sn"));business.put("fact_id",fact);business.put("blocked_action",action);carriers.issue(company,business,ctx,result,"物流自动流程");}
    @SuppressWarnings("unchecked") static Map<String,Object> object(Object v){if(v instanceof Map)return (Map<String,Object>)v;try{return JSON.readValue(String.valueOf(v),Map.class);}catch(Exception e){throw new IllegalArgumentException("原快递执行快照无法解析");}}
}
